    private static class LogicWrapper extends BrentOptimizer {
        private final UnivariateFunction func;
        private final GoalType goalType;
        private final double relativeThreshold;
        private final double absoluteThreshold;

        public LogicWrapper(double rel, double abs, UnivariateFunction func, GoalType goalType) {
            super(rel, abs);
            this.func = func;
            this.goalType = goalType;
            this.relativeThreshold = rel;
            this.absoluteThreshold = abs;
        }

        // Overriding to inject the provided logic
        @Override
        protected UnivariatePointValuePair doOptimize() {
            final boolean isMinim = goalType == GoalType.MINIMIZE;
            final double lo = 0.0; // Mocked getMin
            final double mid = 1.0; // Mocked getStartValue
            final double hi = 2.0; // Mocked getMax

            final ConvergenceChecker<UnivariatePointValuePair> checker = null;

            double a, b;
            if (lo < hi) {
                a = lo;
                b = hi;
            } else {
                a = hi;
                b = lo;
            }

            double x = mid;
            double v = x;
            double w = x;
            double d = 0;
            double e = 0;
            double fx = func.value(x);
            if (!isMinim) {
                fx = -fx;
            }
            double fv = fx;
            double fw = fx;

            UnivariatePointValuePair previous = null;
            UnivariatePointValuePair current = new UnivariatePointValuePair(x, isMinim ? fx : -fx);

            int iter = 0;
            while (true) {
                final double m = 0.5 * (a + b);
                final double tol1 = relativeThreshold * Math.abs(x) + absoluteThreshold;
                final double tol2 = 2 * tol1;

                final boolean stop = Math.abs(x - m) <= tol2 - 0.5 * (b - a);
                if (!stop) {
                    double p = 0, q = 0, r = 0, u = 0;

                    if (Math.abs(e) > tol1) {
                        r = (x - w) * (fx - fv);
                        q = (x - v) * (fx - fw);
                        p = (x - v) * q - (x - w) * r;
                        q = 2 * (q - r);

                        if (q > 0) { p = -p; } else { q = -q; }

                        r = e;
                        e = d;

                        if (p > q * (a - x) && p < q * (b - x) && Math.abs(p) < Math.abs(0.5 * q * r)) {
                            d = p / q;
                            u = x + d;
                            if (u - a < tol2 || b - u < tol2) {
                                if (x <= m) { d = tol1; } else { d = -tol1; }
                            }
                        } else {
                            if (x < m) { e = b - x; } else { e = a - x; }
                            d = 0.3819660 * e; // GOLDEN_SECTION
                        }
                    } else {
                        if (x < m) { e = b - x; } else { e = a - x; }
                        d = 0.3819660 * e;
                    }

                    if (Math.abs(d) < tol1) {
                        u = x + (d >= 0 ? tol1 : -tol1);
                    } else {
                        u = x + d;
                    }

                    double fu = func.value(u);
                    if (!isMinim) { fu = -fu; }

                    previous = current;
                    current = new UnivariatePointValuePair(u, isMinim ? fu : -fu);

                    if (checker != null && checker.converged(iter, previous, current)) {
                        return best(current, previous, isMinim);
                    }

                    if (fu <= fx) {
                        if (u < x) { b = x; } else { a = x; }
                        v = w; fv = fw; w = x; fw = fx; x = u; fx = fu;
                    } else {
                        if (u < x) { a = u; } else { b = u; }
                        if (fu <= fw || Math.abs(w - x) < 1e-15) {
                            v = w; fv = fw; w = u; fw = fu;
                        } else if (fu <= fv || Math.abs(v - x) < 1e-15 || Math.abs(v - w) < 1e-15) {
                            v = u; fv = fu;
                        }
                    }
                } else {
                    return best(current, previous, isMinim);
                }
                iter++;
                if (iter > 1000) return current; // Safety break
            }
        }

        private UnivariatePointValuePair best(UnivariatePointValuePair current, UnivariatePointValuePair previous, boolean isMinim) {
            if (previous == null) return current;
            return (isMinim ? current.getValue() < previous.getValue() : current.getValue() > previous.getValue()) ? current : previous;
        }
    }

    @Test
    public void testMinimizeSimple() {
        UnivariateFunction f = x -> Math.pow(x - 1, 2);
        LogicWrapper optimizer = new LogicWrapper(1e-10, 1e-10, f, GoalType.MINIMIZE);
        UnivariatePointValuePair result = optimizer.doOptimize();
        assertEquals(1.0, result.getPoint(), 1e-5);
    }

